<?php
namespace App\Services;
class BackupDiagnostics {
 public static function paths(){return [storage_path('logs/website-backup.log'),dirname(base_path()).'/footstep-site-backups/request-events.log'];}
 public static function record($code,$status,$id,$operation,$exception=null,$fields=[]){$event=['at'=>gmdate('c'),'request_id'=>$id,'event'=>$code,'http_status'=>$status,'operation'=>$operation,'exception_type'=>$exception?get_class($exception):null,'failure'=>$exception?self::failure($exception):null,'invalid_fields'=>array_values(array_intersect($fields,['password','archive_password','archive','action','scope','confirm']))];$line=json_encode($event,JSON_UNESCAPED_SLASHES)."\n";foreach(self::paths()as $path){if(!is_dir(dirname($path))||!is_writable(dirname($path)))continue;try{if(is_file($path)&&filesize($path)>2097152)@rename($path,$path.'.1');if(@file_put_contents($path,$line,FILE_APPEND|LOCK_EX)!==false){@chmod($path,0600);return;}}catch(\Throwable $ignored){}}error_log('Footstep backup diagnostic: '.$line);}
 public static function recent(){foreach(self::paths()as $path){if(!is_file($path)||!is_readable($path))continue;$f=@fopen($path,'rb');if(!$f)continue;$size=filesize($path);if($size>65536){fseek($f,-65536,SEEK_END);fgets($f);}$rows=[];while(($line=fgets($f))!==false){$row=json_decode($line,true);if(is_array($row))$rows[]=array_intersect_key($row,array_flip(['at','request_id','event','http_status','operation','exception_type','invalid_fields','failure']));}fclose($f);return array_slice($rows,-50);}return [];}
 public static function classify($e){if($e instanceof \PDOException)return ['database_connection_or_query_failed','Database connection/query ব্যর্থ। DB settings ও MySQL access পরীক্ষা করুন।'];$message=$e->getMessage();if(stripos($message,'permission denied')!==false||stripos($message,'backup storage')!==false||stripos($message,'backup record could not be saved')!==false||stripos($message,'mkdir')!==false)return ['backup_storage_not_writable','Backup-এর private folder তৈরি/লেখা যাচ্ছে না। Hosting ownership ও write permission পরীক্ষা করুন।'];if(stripos($message,'configuration is invalid')!==false)return ['backup_configuration_invalid','Backup configuration/APP_KEY পাওয়া যায়নি। Server configuration পরীক্ষা করুন।'];if(stripos($message,'ZIP')!==false)return ['zip_support_or_archive_error','ZIP support/archive operation ব্যর্থ। PHP ZIP extension ও AES encryption support পরীক্ষা করুন।'];return ['backup_server_error','Server backup request সম্পন্ন করতে পারেনি। নিচের request ID দিয়ে diagnostic log দেখুন।'];}

 public static function failure($e){$m=strtolower($e->getMessage());$code='backup_file_operation_failed';$message='File/ZIP operation ব্যর্থ। নিচের stage/file ও worker log পরীক্ষা করুন।';
 if(strpos($m,'quota')!==false||strpos($m,'no space')!==false||strpos($m,'not enough free space')!==false){$code='backup_disk_space_or_quota';$message='Hosting disk space/account quota শেষ বা প্রয়োজনের তুলনায় কম। Disk Usage/hosting support পরীক্ষা করুন।';}
 elseif(strpos($m,'too many open')!==false){$code='backup_open_file_limit';$message='Server-এর open-file limit শেষ হয়েছে। File batch ছোট করা হয়েছে; আবার হলে hosting limit পরীক্ষা করুন।';}
 elseif(strpos($m,'disappeared')!==false||strpos($m,'no such file')!==false){$code='backup_source_missing';$message='তালিকায় থাকা file পরে পাওয়া যায়নি। Upload/optimization/update বন্ধ রেখে নতুন backup দিন।';}
 elseif(strpos($m,'permission')!==false||strpos($m,'unreadable')!==false||strpos($m,'cannot read source')!==false){$code='backup_source_permission';$message='File পড়া বা private archive-এ লেখার permission নেই। নিচের file ও hosting ownership পরীক্ষা করুন।';}
 elseif(strpos($m,'zip')!==false||strpos($m,'archive')!==false||strpos($m,'temp')!==false){$code='backup_zip_write_failed';$message='ZIP তৈরি/লেখা শেষ হয়নি। Private folder, disk quota ও CLI PHP ZIP support পরীক্ষা করুন।';}
 elseif($e instanceof \PDOException){$code='backup_database_error';$message='Database snapshot ব্যর্থ। MySQL access/compatibility পরীক্ষা করুন।';}
 return ['code'=>$code,'message'=>$message,'source'=>basename($e->getFile()).':'.$e->getLine()];}
 public static function readiness(){ $data=dirname(base_path()).'/footstep-site-backups';$heartbeat=is_file($data.'/worker-heartbeat.json')?json_decode((string)@file_get_contents($data.'/worker-heartbeat.json'),true):[];return ['worker_last_seen'=>$heartbeat['last_seen']??null,'worker_php_version'=>$heartbeat['php_version']??null,'web_php_version'=>PHP_VERSION,'filesystem_free_bytes'=>@disk_free_space($data?:dirname(base_path()))?:null,'private_folder_exists'=>is_dir($data),'private_folder_writable'=>is_dir($data)?is_writable($data):is_writable(dirname(base_path())),'diagnostic_log_writable'=>is_writable(storage_path('logs'))||(is_dir($data)&&is_writable($data)),'php_zip'=>class_exists(\ZipArchive::class),'zip_aes256'=>class_exists(\ZipArchive::class)&&defined('ZipArchive::EM_AES_256')&&method_exists(\ZipArchive::class,'setEncryptionName'),'pdo_mysql'=>extension_loaded('pdo_mysql'),'app_key_present'=>strlen((string)config('app.key'))>=24];}
}
